from typing import List

def find_duplicates(dataset: List[Any]) -> List[Any]:
    freq = {}  # Using a dictionary to count frequencies
    for element in dataset:
        if element in freq:
            freq[element] += 1
        else:
            freq[element] = 1
    duplicates = []  # List to collect duplicates
    for element in dataset:
        if freq[element] >= 2 and element not in duplicates:
            duplicates.append(element)
    return duplicates
print(find_duplicates([1, 2, 3, 4, 5, 5, 6, 7, 1]))  # Output: [1, 5]
